import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { createTaxRateRulesWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await createTaxRateRulesWorkflow(req.scope)
    .run({
      input: {
        rules: [{
          tax_rate_id: "txr_123",
          reference: "product_type",
          reference_id: "ptyp_123"
        }]
      }
    })

  res.send(result)
}

